    centers = [(r,c,grid[r][c]) for r in range(n) for c in range(m) if grid[r][c] not in (0,3)]
    for vertical in (False, True):
        for r,c,color in centers:
            dirs = ((-1,0),(1,0)) if vertical else ((0,-1),(0,1))
            for dr,dc in dirs:
                i,j=r+dr,c+dc
                if 0 <= i < n and 0 <= j < m and grid[i][j] == 3:
                    i+=dr; j+=dc
                while 0 <= i < n and 0 <= j < m and grid[i][j] == 0:
                    out[i][j]=color
                    i+=dr; j+=dc
    # Uncolored 3-crosses mark blank row/column axes.
    crosses=[]
